function productSVG(name, hue="rose"){
  const palettes = {rose:["%23c496a1","%23f4dce3","%2381785a"], sage:["%23919d85","%23e7edde","%2381785a"], lav:["%238e8aa3","%23eceafd","%2381785a"], cream:["%23ebe1c6","%23fffaf0","%2381785a"]};
  const c = palettes[hue] || palettes.rose;
  return `data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='900' height='700' viewBox='0 0 900 700'><defs><linearGradient id='g' x1='0' x2='1' y1='0' y2='1'><stop stop-color='${c[1]}'/><stop offset='1' stop-color='${c[0]}'/></linearGradient></defs><rect width='900' height='700' rx='64' fill='url(%23g)'/><circle cx='135' cy='110' r='70' fill='white' opacity='.35'/><circle cx='780' cy='595' r='130' fill='white' opacity='.28'/><path d='M248 434c100-154 302-148 404 0-124 70-281 76-404 0Z' fill='white' opacity='.65'/><path d='M340 319c17-80 91-145 110-145s94 65 111 145c-52 31-170 31-221 0Z' fill='white' opacity='.75'/><text x='450' y='535' text-anchor='middle' font-family='Georgia,serif' font-size='52' fill='${c[2]}'>${encodeURIComponent(name)}</text><text x='450' y='590' text-anchor='middle' font-family='Arial' font-size='24' fill='${c[2]}' opacity='.75'>Bai Boua Shop</text></svg>`;
}
